"""Generate Flutter primitives from the handoff. Run from any directory."""
import json
import subprocess
from pathlib import Path

mobile = Path(__file__).resolve().parents[1]
tokens = json.loads((mobile.parent / "docs/design/tokens.json").read_text())


def identifier(name):
    first, *rest = name.split("-")
    return first + "".join(piece.title() for piece in rest)


def number(value):
    return float(value.removesuffix("px"))


lines = [
    "// Generated by tool/generate_tokens.py. Edit docs/design/tokens.json.",
    "import 'package:flutter/material.dart';",
    "",
    "class Palette {",
    "  const Palette(this.brightness);",
    "  final Brightness brightness;",
    "  bool get _dark => brightness == Brightness.dark;",
    "  static Palette of(BuildContext context) => Palette(Theme.of(context).brightness);",
]
for token in tokens["color"]["tokens"]:
    name, value = identifier(token["name"]), token["value"]
    if isinstance(value, str):
        expression = identifier(value.strip("{}"))
    else:
        colors = [f"const Color(0xff{value[mode][1:]})" for mode in ("dark", "light")]
        expression = f"_dark ? {colors[0]} : {colors[1]}"
    lines.append(f"  Color get {name} => {expression};")
lines.extend(["}", "", "abstract final class Metrics {"])
for group in ("spacing", "radius"):
    for token in tokens[group]["tokens"]:
        lines.append(f"  static const {identifier(token['name'])} = {number(token['value'])};")
lines.extend(["}", "", "abstract final class TypeScale {"])
for group in tokens["type"]["groups"]:
    family = tokens["type"]["families"][group["family"]].split(",")[0].strip('"')
    for style in group["styles"]:
        size = number(style["fontSize"])
        height = number(style["lineHeight"])
        lines.append(
            f"  static const {identifier(style['name'])} = TextStyle("
            f"fontFamily: '{family}', fontSize: {size}, height: {height}/{size}, "
            f"fontWeight: FontWeight.w{style['fontWeight']}, "
            f"letterSpacing: {number(style.get('letterSpacing', '0px'))});"
        )
lines.append("}")
(mobile / "lib/theme").mkdir(exist_ok=True)
(mobile / "lib/theme/tokens.dart").write_text("\n".join(lines) + "\n")
subprocess.run(["dart", "format", "lib/theme/tokens.dart"], cwd=mobile, check=True)
